      .filter((hero) => needle === '' || this.matches(hero, needle))
      .sort((a, b) => b.powerIndex - a.powerIndex)
      .map((hero) => ({
        hero,
        initials: initialsOf(hero.name),
        statusVariant: statusVariantOf(hero.status),
        link: ['/detail', hero.id],
