  catch { const data = await readFile(join(DIST, 'index.html')); res.writeHead(200, { 'content-type': 'text/html' }); res.end(data); }
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const origin = `http://127.0.0.1:${server.address().port}`;
function probe(anchor) {
  const vw = window.innerWidth; const fails = [];
  const sel = (el) => el.tagName.toLowerCase() + (el.id ? '#' + el.id : '') + (typeof el.className === 'string' && el.className ? '.' + el.className.trim().split(/\s+/)[0] : '');
  const scrollAncestor = (el, root) => { for (let e = el.parentElement; e && e !== root.parentElement; e = e.parentElement) { const o = getComputedStyle(e).overflowX; if (o === 'auto' || o === 'scroll') return true; } return false; };
  const exempt = (el, r) => { if (el.closest('[aria-hidden="true"]')) return true; for (let e = el; e; e = e.parentElement) { const c = getComputedStyle(e); if (c.display === 'none' || c.visibility === 'hidden') return true; } return Math.max(r.width, r.height) <= 1; };
  if (document.documentElement.scrollWidth - vw > 1) fails.push({ kind: 'page-scroll', detail: document.documentElement.scrollWidth + ' vs ' + vw });
  const root = document.querySelector(anchor) || document.body;
  for (const el of root.querySelectorAll('*')) {
    const r = el.getBoundingClientRect(); if (r.width <= 0 || r.height <= 0) continue; if (exempt(el, r)) continue;
    const cs = getComputedStyle(el);
    if ((r.right - vw > 1 || r.left < -1) && !scrollAncestor(el, root)) fails.push({ kind: 'escape', selector: sel(el), detail: Math.round(r.left) + '..' + Math.round(r.right) });
    const hx = (cs.overflowX === 'hidden' || cs.overflowX === 'clip') && el.scrollWidth - el.clientWidth > 1;
    const hy = (cs.overflowY === 'hidden' || cs.overflowY === 'clip') && el.scrollHeight - el.clientHeight > 1;
    if (hx || hy) fails.push({ kind: 'clip', selector: sel(el) });
  }
  return fails;
}
const routes = ['dashboard', 'roster', 'roster?q=silver', 'detail/HRO-0012', 'detail/HRO-0040', 'missions', 'threats', 'recruit', 'settings'];
const browser = await chromium.launch();
let bad = 0;
try {
  for (const route of routes) {
    const out = [];
    for (const width of [375, 768, 1280]) {
      const ctx = await browser.newContext({ viewport: { width, height: 800 } });
      const page = await ctx.newPage();
      const errors = [];
      page.on('pageerror', (e) => errors.push(String(e.message)));
      await page.goto(`${origin}/${route}`, { waitUntil: 'networkidle' });
      await page.waitForTimeout(300);
      const fails = await page.evaluate(probe, 'app-root');
      if (errors.length) fails.push({ kind: 'pageerror', detail: errors[0] });
      for (const f of fails) out.push({ width, ...f });
      await ctx.close();
    }
    console.log(route, out.length === 0 ? 'OK' : JSON.stringify(out.slice(0, 8)));
    bad += out.length;
  }
} finally { await browser.close(); server.close(); }
process.exit(bad ? 1 : 0);
EOF
