  try { const d = await readFile(join(DIST, path)); res.writeHead(200, { 'content-type': extname(path) === '.js' ? 'text/javascript' : extname(path) === '.css' ? 'text/css' : 'text/html' }); res.end(d); }
  catch { res.writeHead(200, { 'content-type': 'text/html' }); res.end(await readFile(join(DIST, 'index.html'))); }
});
await new Promise((r) => server.listen(0, '127.0.0.1', r));
const origin = `http://127.0.0.1:${server.address().port}`;
const browser = await chromium.launch();
const errors = [];
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const step = async (name, fn) => { try { const r = await fn(); console.log('PASS', name, r ?? ''); } catch (e) { console.log('FAIL', name, String(e.message).split('\n')[0]); } };
await page.goto(`${origin}/detail/HRO-0012`, { waitUntil: 'networkidle' });

await step('edit tab shows form', async () => { await page.getByRole('button', { name: 'Edit', exact: true }).click(); await page.getByLabel('Name').waitFor(); return await page.getByLabel('Name').inputValue(); });
await step('edit name saves and reflects on roster', async () => {
  await page.getByLabel('Name').fill('Dr. Ion Mk II');
  await page.getByRole('button', { name: 'Save', exact: true }).click();
  await page.getByRole('heading', { name: 'Dr. Ion Mk II', level: 1 }).waitFor();
  await page.goto(`${origin}/roster`, { waitUntil: 'networkidle' });
  await page.getByText('Dr. Ion Mk II').first().waitFor();
});
await step('dashboard reflects edit in roster table', async () => { await page.goto(`${origin}/dashboard`, { waitUntil: 'networkidle' }); return (await page.getByText('Dr. Ion Mk II').count()) > 0; });
await step('deploy reserve hero logs a live mission', async () => {
  await page.goto(`${origin}/detail/HRO-0021`, { waitUntil: 'networkidle' });
  await page.getByRole('button', { name: 'Deploy' }).click();
  await page.getByRole('button', { name: 'Missions', exact: true }).click();
  await page.waitForTimeout(200);
  return (await page.getByText('Rapid deployment').count()) > 0 ? 'mission row on detail' : 'none';
});
await step('missions screen lists live deployment', async () => { await page.goto(`${origin}/missions`, { waitUntil: 'networkidle' }); return (await page.getByText('Rapid deployment').count()) + ' row(s)'; });
await step('recruit creates hero and opens detail', async () => {
  await page.goto(`${origin}/recruit`, { waitUntil: 'networkidle' });
  await page.getByLabel('Name').fill('Test Recruit');
  await page.getByLabel('Alias').fill('Pat Tester');
  await page.getByRole('button', { name: 'Recruit hero' }).click();
  await page.waitForURL(/detail\/HRO-0082/);
  return page.url();
});
await step('recruit validation blocks empty submit', async () => { await page.goto(`${origin}/recruit`, { waitUntil: 'networkidle' }); await page.getByRole('button', { name: 'Recruit hero' }).click(); await page.waitForTimeout(200); return page.url().endsWith('/recruit') ? 'stayed on recruit' : 'navigated'; });
await step('topbar search filters roster', async () => { await page.goto(`${origin}/dashboard`, { waitUntil: 'networkidle' }); await page.getByRole('searchbox', { name: 'Search heroes' }).fill('silver'); await page.keyboard.press('Enter'); await page.waitForURL(/roster\?q=silver/); await page.waitForTimeout(200); return (await page.getByRole('searchbox', { name: 'Search' }).inputValue()) + ' / rows: ' + (await page.locator('tbody tr').count()); });
await step('settings theme switch toggles dark class', async () => { await page.goto(`${origin}/settings`, { waitUntil: 'networkidle' }); const before = await page.evaluate(() => document.documentElement.classList.contains('dark')); await page.getByRole('switch').click(); await page.waitForTimeout(150); const after = await page.evaluate(() => document.documentElement.classList.contains('dark')); return before + ' -> ' + after; });
await step('settings reset restores the roster', async () => { await page.getByRole('button', { name: 'Reset example data' }).click(); await page.goto(`${origin}/roster`, { waitUntil: 'networkidle' }); return (await page.getByText('of 12 heroes').count()) + ' footer match'; });
await step('retire dialog opens and closes', async () => { await page.goto(`${origin}/detail/HRO-0007`, { waitUntil: 'networkidle' }); await page.getByRole('button', { name: 'Retire', exact: true }).click(); await page.getByRole('dialog').waitFor(); await page.getByRole('button', { name: 'Cancel' }).last().click(); return 'ok'; });

// Edit tab at narrow width: responsive probe on the form.
const phone = await browser.newPage({ viewport: { width: 375, height: 800 } });
phone.on('pageerror', (e) => errors.push('phone pageerror: ' + e.message));
await phone.goto(`${origin}/detail/HRO-0012`, { waitUntil: 'networkidle' });
await phone.getByRole('button', { name: 'Edit', exact: true }).click();
await phone.waitForTimeout(200);
const scroll = await phone.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
console.log('375 edit tab page overflow px:', scroll);
console.log('errors:', errors.length ? errors : 'none');
await browser.close(); server.close();
EOF
node "$TMPDIR/flows.mjs" "$(pwd)/dist/angular-jig/browser" "file:///D:/Repos/angular-jig/node_modules/playwright/index.mjs" 2>&1 | tail -40

