cd D:/Repos/angular-jig; cat > "$TMPDIR/all-routes.mjs" <<'EOF'
import { join } from 'node:path';
const ROOT = process.argv[2];
const { serveStatic, launchChromium } = await import(`file://${ROOT}/harness/playwright/serve-and-visit.mjs`);
const { assertResponsive } = await import(`file://${ROOT}/harness/gate/check-responsive.mjs`);
const srv = await serveStatic(join(ROOT, 'dist', 'angular-jig', 'browser'), { spaFallback: true });
const browser = await launchChromium();
const routes = ['dashboard', 'roster', 'roster?q=silver', 'detail/HRO-0012', 'detail/HRO-0040', 'missions', 'threats', 'recruit', 'settings'];
let bad = 0;
try {
  for (const route of routes) {
    const { failures } = await assertResponsive({ origin: srv.origin, route, browser, anchorSelector: 'app-root' });
    console.log(route, failures.length === 0 ? 'OK' : JSON.stringify(failures.slice(0, 6)));
    bad += failures.length;
  }
} finally {
  await browser.close();
  await srv.close?.();
}
process.exit(bad ? 1 : 0);
EOF
node "$TMPDIR/all-routes.mjs" "$(pwd -W 2>/dev/null || pwd)" 2>&1 | tail -30
